using System;
using System.Text;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using SecuredClient.Crypto;
using SecuredClient.Provider;

namespace SecuredClientTest.Crypto
{
    [TestClass]
    public class CertificateChainValidatorTest
    {
        [TestMethod]
        public void TestBankdataChainIsValid()
        {
            var chainEncoded = "";

            var block = Encoding.UTF8.GetString(Convert.FromBase64String(chainEncoded));
            var reader = new PemBlockReader(block);
            var certs = reader.ReadCertificates();

            CertificateStore.Instance.AddTrustedCaCertificate(new BankdataSystemtestServiceProvider().RootCaCertificate);
            new CertificateChainValidator(CertificateStore.Instance.TrustedCaCertificates).AssertValid(certs);
        }

    }
}
